program='''def transform(grid):
    n = len(grid)
    m = n // 2
    color = grid[m][m]
    out = [[7] * n for _ in range(n)]
    cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
    top = all(r <= m for r, c in cells)
    left = all(c <= m for r, c in cells)
    if top and left:
        for i in range(m + 1):
            out[i][i] = color
    elif top:
        for i in range(m + 1):
            out[i][n - 1 - i] = color
    elif left:
        for i in range(m + 1, n):
            out[i][n - 1 - i] = color
    else:
        for i in range(m + 1, n):
            out[i][i] = color
    return out
'''
